import {
  type AuthoringArtifact,
  type FoldIssue,
  attach,
  requiredFieldsIssues,
  universalFoldsIssues,
} from './marketplace-tier.js';

// ─── Required-field sets (the source of the effective-required manifest) ─────

/** standardFloor — the upstream-base always-required fields (code.claude.com plugin-marketplaces). */
export const MARKETPLACE_CATALOG_BASE_REQUIRED = ['name', 'owner', 'plugins'] as const;

/** The IS-overlay required delta (beyond the base floor). */
export const MARKETPLACE_CATALOG_OVERLAY_REQUIRED = [
  'version',
  'description',
  'license',
  'homepage',
  'keywords',
] as const;

/** Effective required = base ∪ overlay = the IS 8-field marketplace set (NON-NEGOTIABLE). */
export const MARKETPLACE_CATALOG_REQUIRED_FIELDS = [
  ...MARKETPLACE_CATALOG_BASE_REQUIRED,
  ...MARKETPLACE_CATALOG_OVERLAY_REQUIRED,
] as const;

// ─── Constraint constants (mirror the JSON Schemas exactly) ──────────────────

/** code.claude.com plugin-marketplaces kebab-case name surface (upstream-base). */
export const MARKETPLACE_NAME_PATTERN = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/;
/** code.claude.com plugin-marketplaces name length ceiling (upstream-base). */
export const MARKETPLACE_NAME_MAX = 64;
/** Strict SemVer 2.0.0 (is-overlay — stricter than the legacy IS prefix match). */
export const SEMVER_PATTERN =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === 'string');
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isUri(value: string): boolean {
  try {
    new URL(value);
    return true;
  } catch {
    return false;
  }
}

// ─── Layer 1: upstream base (authored by THEM) ───────────────────────────────

/**
 * The code.claude.com plugin-marketplaces projection. Required presence of the
 * standardFloor ([name, owner, plugins]) + type/constraint on the upstream-owned
 * fields (kebab-case name, object owner with a required inner name, non-empty
 * array of plugin entries each requiring [name, source]). Length of `description`
 * is intentionally NOT capped here — the universal disclosureMarkers fold (1536)
 * is the operative cap (encoding a tighter cap would violate the
 * monotonic-additive invariant against the IS 1536 tier).
 */
export function upstreamBaseIssues(artifact: AuthoringArtifact): FoldIssue[] {
  const issues: FoldIssue[] = [
    ...requiredFieldsIssues(artifact, MARKETPLACE_CATALOG_BASE_REQUIRED),
  ];

  if ('name' in artifact) {
    const name = artifact['name'];
    if (typeof name !== 'string') {
      issues.push({ message: 'name must be a string', path: ['name'] });
    } else {
      if (name.length > MARKETPLACE_NAME_MAX) {
        issues.push({
          message: `name must be at most ${MARKETPLACE_NAME_MAX} characters`,
          path: ['name'],
        });
      }
      if (!MARKETPLACE_NAME_PATTERN.test(name)) {
        issues.push({
          message: 'name must be kebab-case (lowercase letters, digits, hyphens)',
          path: ['name'],
        });
      }
    }
  }

  if ('owner' in artifact) {
    const owner = artifact['owner'];
    if (!isPlainObject(owner)) {
      issues.push({ message: 'owner must be an object', path: ['owner'] });
    } else {
      for (const key of ['name'] as const) {
        if (!(key in owner)) {
          issues.push({ message: `owner.${key} is required`, path: ['owner', key] });
        }
      }
    }
  }

  if ('plugins' in artifact) {
    const plugins = artifact['plugins'];
    if (!Array.isArray(plugins)) {
      issues.push({ message: 'plugins must be an array', path: ['plugins'] });
    } else {
      if (plugins.length < 1) {
        issues.push({ message: 'plugins must not be empty', path: ['plugins'] });
      }
      plugins.forEach((entry, index) => {
        if (!isPlainObject(entry)) {
          issues.push({
            message: 'plugins entry must be an object',
            path: ['plugins', String(index)],
          });
          return;
        }
        for (const key of ['name', 'source'] as const) {
          if (!(key in entry)) {
            issues.push({
              message: `plugins[${index}].${key} is required`,
              path: ['plugins', String(index), key],
            });
          }
        }
      });
    }
  }

  if ('metadata' in artifact && !isPlainObject(artifact['metadata'])) {
    issues.push({ message: 'metadata must be an object', path: ['metadata'] });
  }

  return issues;
}

// ─── Layer 3: IS overlay (authored by US) ────────────────────────────────────

/**
 * The IS-only delta: five fields promoted to IS-required (version, description,
 * license, homepage, keywords) + the SemVer narrowing on version. A field whose
 * type is already enforced by the base (the overlay only adds it to required) is
 * not re-typed here — its presence is the required check — to keep messages
 * single-sourced.
 */
export function isOverlayIssues(artifact: AuthoringArtifact): FoldIssue[] {
  const issues: FoldIssue[] = [
    ...requiredFieldsIssues(artifact, MARKETPLACE_CATALOG_OVERLAY_REQUIRED),
  ];

  if ('version' in artifact) {
    const version = artifact['version'];
    if (typeof version !== 'string') {
      issues.push({ message: 'version must be a string', path: ['version'] });
    } else if (!SEMVER_PATTERN.test(version)) {
      issues.push({ message: 'version must be strict SemVer 2.0.0', path: ['version'] });
    }
  }

  if ('description' in artifact && typeof artifact['description'] !== 'string') {
    issues.push({ message: 'description must be a string', path: ['description'] });
  }

  if ('license' in artifact && typeof artifact['license'] !== 'string') {
    issues.push({ message: 'license must be a string', path: ['license'] });
  }

  if ('homepage' in artifact) {
    const homepage = artifact['homepage'];
    if (typeof homepage !== 'string') {
      issues.push({ message: 'homepage must be a string', path: ['homepage'] });
    } else if (!isUri(homepage)) {
      issues.push({ message: 'homepage must be a valid URI', path: ['homepage'] });
    }
  }

  if ('keywords' in artifact && !isStringArray(artifact['keywords'])) {
    issues.push({ message: 'keywords must be an array of strings', path: ['keywords'] });
  }

  return issues;
}

// ─── The composition (allOf of base + universal folds + overlay) ─────────────

/** Every issue from the three composed layers, in layer order. */
export function marketplaceCatalogIssues(artifact: AuthoringArtifact): FoldIssue[] {
  return [
    ...upstreamBaseIssues(artifact),
    ...universalFoldsIssues(artifact),
    ...isOverlayIssues(artifact),
  ];
}

/** The marketplace-catalog contract — pure allOf composition (base ∧ universalFolds ∧ overlay). */
export const MarketplaceCatalogSchema = attach(marketplaceCatalogIssues);

export type MarketplaceCatalog = AuthoringArtifact;
